571	\begin{lemma}[Extensionality of finite distributions]\label{lem:distribution-ext-support}
572		\lean{MIPStarRE.QPBT.Distribution.ext_of_support_of_weight}
573		\leanok
574		Two finite distributions with the same support and the same weight at every
575		point are equal.
576	\end{lemma}
577	\begin{proof}
578		\leanok
