583	\begin{lemma}[Composition of push-forwards]\label{lem:distribution-map-comp}
584		\lean{MIPStarRE.QPBT.Distribution.map_map}
585		\leanok
586		Let $\mu$ be a finite distribution on $A$, and let $e\colon A\to B$ and
587		$f\colon B\to C$. Then
588		\[
589			f_\ast(e_\ast\mu)=(f\circ e)_\ast\mu.
590		\]
591	\end{lemma}
592	\begin{proof}
593		\leanok
594		\uses{lem:distribution-ext-support}
595		The supports agree by composition of finite images.  For each $c\in C$,
596		partition the fiber of $f\circ e$ over $c$ by the intermediate value $e(a)$;
597		the corresponding sums of weights agree.
