612	\begin{lemma}[Uniform push-forward along a balanced map]\label{lem:uniform-map-equal-fibers}
613		\lean{MIPStarRE.QPBT.uniformDistribution_map_of_card_fiber}
614		\leanok
615		Let $A$ and $B$ be nonempty finite sets and let $e\colon A\to B$. If there is
616		an integer $c$ such that $|e^{-1}(b)|=c$ for every $b\in B$, then
617		$e_\ast\operatorname{Unif}(A)=\operatorname{Unif}(B)$.
618	\end{lemma}
619	\begin{proof}
620		\leanok
621		\uses{lem:distribution-ext-support, lem:uniform-distribution-weight}
622		Every fiber is nonempty, so $e$ is surjective and both supports are $B$.
623		Counting the fibers gives $|A|=c|B|$; summing the weight $1/|A|$ over a
