666	\begin{lemma}[Dependent uniform sampling as a product push-forward]\label{lem:uniform-bind-map}
667		\lean{MIPStarRE.QPBT.bind_uniformDistribution_map}
668		\leanok
669		Let $A$ and $B$ be nonempty finite sets and let $g\colon A\to B\to C$.
670		Sampling $a$ uniformly from $A$, then $b$ uniformly from $B$, and returning
671		$g(a,b)$ has the same law as pushing $\operatorname{Unif}(A\times B)$ forward
672		along $(a,b)\mapsto g(a,b)$.
