537	\begin{lemma}[Formalization support for line incidence]\label{lem:line-rep-incidence}
538		\lean{MIPStarRE.QPBT.mem_linePoints_lineRepMap}
539		\leanok
540		\uses{def:line-representative, def:line, lem:line-rep-kernel}
541		This is not a named statement of the source article; it is the incidence half of Definition~\ref{def:line-representative}, in the form used by the line-versus-point samplers of Chapter~\ref{chap:qpbt-test}. For all $u, v \in \F_q^m$,
542		\[
543			u \in \ell\bigl(L^{\mathrm{Ln}}_v(u),\, v\bigr)\;.
544		\]
545	\end{lemma}
546	\begin{proof}
547		\leanok
548		\uses{lem:line-rep-kernel, def:line}
549		By Lemma~\ref{lem:line-rep-kernel} there is $t \in \F_q$ with $u - L^{\mathrm{Ln}}_v(u) = t\,v$, so $u = L^{\mathrm{Ln}}_v(u) + t\,v$, which lies in $\ell\bigl(L^{\mathrm{Ln}}_v(u), v\bigr)$ by Equation~\eqref{eq:line-set}.
550	\end{proof}
